336	```go
337	// Package finding defines the scanner payload carried on findings.* subjects.
338	package finding
339	
340	import (
341		"encoding/json"
342		"errors"
343		"fmt"
344		"strings"
345		"time"
346	)
347	
348	// Evidence is the matched text and its surrounding lines.
349	type Evidence struct {
350		Match   string `json:"match"`
351		Context string `json:"context"`
352	}
353	
354	// Finding is one scanner result.
355	type Finding struct {
356		ID          string    `json:"id"`
357		Fingerprint string    `json:"fingerprint"`
358		Scanner     string    `json:"scanner"`
359		Rule        string    `json:"rule"`
360		Severity    string    `json:"severity"`
361		Repo        string    `json:"repo"`
362		Path        string    `json:"path"`
363		Line        int       `json:"line"`
364		Title       string    `json:"title"`
365		Description string    `json:"description"`
366		Evidence    Evidence  `json:"evidence"`
367		EmittedAt   time.Time `json:"emitted_at"`
368	}
369	
370	// ErrNoFingerprint is returned when the payload has no fingerprint.
371	var ErrNoFingerprint = errors.New("finding: fingerprint is required")
372	
373	// SafeMatch returns the matched text, masked when it is a leaked credential,
374	// so the secret is not copied into tickets, chat or logs.
375	func (f Finding) SafeMatch() string {
376		if f.Scanner != "gitleaks" {
377			return f.Evidence.Match
378		}
379		return mask(f.Evidence.Match)
380	}
381	
382	func mask(s string) string {
383		if len(s) <= 8 {
384			return strings.Repeat("*", len(s))
385		}
386		return s[:4] + strings.Repeat("*", len(s)-4)
387	}
388	
389	// ErrBadLine is returned with a usable Finding when the payload's line is not
390	// an integer. Line is left at 0; the rest of the finding is intact.
391	var ErrBadLine = errors.New("finding: line is not an integer")
392	
393	// Parse decodes a message payload into a Finding.
394	func Parse(data []byte) (Finding, error) {
395		var f Finding
396		var lineErr error
397		if err := json.Unmarshal(data, &f); err != nil {
398			var typeErr *json.UnmarshalTypeError
399			if !errors.As(err, &typeErr) || typeErr.Field != "line" {
400				return Finding{}, fmt.Errorf("finding: decode: %w", err)
401			}
402			f.Line = 0
403			lineErr = ErrBadLine
404		}
405		if f.Fingerprint == "" {
406			return Finding{}, ErrNoFingerprint
407		}
408		return f, lineErr
409	}
410	```
