553	```go
554	package ticket
555	
556	import (
557		"context"
558		"sync"
559		"time"
560	)
561	
562	// limiter spaces requests evenly so the client stays under the platform's
563	// per-token rate limit.
564	type limiter struct {
565		mu    sync.Mutex
566		every time.Duration
567		next  time.Time
568	}
569	
570	func newLimiter(perSecond float64) *limiter {
571		if perSecond <= 0 {
572			return &limiter{}
573		}
574		return &limiter{every: time.Duration(float64(time.Second) / perSecond)}
575	}
576	
577	func (l *limiter) wait(ctx context.Context) error {
578		if l.every == 0 {
579			return nil
580		}
581		l.mu.Lock()
582		now := time.Now()
583		if l.next.Before(now) {
584			l.next = now
585		}
586		at := l.next
587		l.next = l.next.Add(l.every)
588		l.mu.Unlock()
589	
590		d := time.Until(at)
591		if d <= 0 {
592			return nil
593		}
594		t := time.NewTimer(d)
595		defer t.Stop()
596		select {
597		case <-ctx.Done():
598			return ctx.Err()
599		case <-t.C:
600			return nil
601		}
602	}
603	```
