625	// ErrRateLimited is returned when the platform answers 429.
626	var ErrRateLimited = errors.New("ticket: rate limited")
627	
628	// Ticket is the create request body.
629	type Ticket struct {
630		Title       string   `json:"title"`
631		Body        string   `json:"body"`
632		Severity    string   `json:"severity"`
633		ExternalRef string   `json:"external_ref"`
634		Labels      []string `json:"labels"`
635	}
636	
637	// FromFinding maps a finding to a ticket.
638	func FromFinding(f finding.Finding) Ticket {
639		var b strings.Builder
640		fmt.Fprintf(&b, "%s:%d\n\n%s\n\nMatch:\n%s\n", f.Path, f.Line, f.Description, f.SafeMatch())
641		return Ticket{
642			Title:       f.Title,
643			Body:        b.String(),
644			Severity:    f.Severity,
645			ExternalRef: f.Fingerprint,
646			Labels:      []string{"scanner:" + f.Scanner, "repo:" + f.Repo},
647		}
648	}
649	
650	// Client creates tickets.
651	type Client struct {
652		url     string
653		token   string
654		http    *http.Client
655		limiter *limiter
656	}
657	
658	// New returns a Client for the platform at baseURL. perSecond caps the
659	// request rate of this client; 0 disables the cap.
660	func New(baseURL, token string, perSecond float64) *Client {
661		return &Client{
662			url:     strings.TrimRight(baseURL, "/"),
663			token:   token,
664			http:    &http.Client{Timeout: 5 * time.Second},
665			limiter: newLimiter(perSecond),
666		}
667	}
668	
669	// FindByExternalRef returns the id of an existing ticket with the given
670	// external_ref, or "" if there is none.
671	func (c *Client) FindByExternalRef(ctx context.Context, ref string) (string, error) {
672		req, err := http.NewRequestWithContext(ctx, http.MethodGet, c.url+"/tickets?external_ref="+url.QueryEscape(ref), nil)
673		if err != nil {
674			return "", err
675		}
676		resp, err := c.do(ctx, req)
677		if err != nil {
678			return "", err
679		}
680		defer resp.Body.Close()
681		if err := checkStatus(resp, "search"); err != nil {
682			return "", err
683		}
684		var out []struct {
685			ID          string `json:"id"`
686			ExternalRef string `json:"external_ref"`
687		}
688		if err := json.NewDecoder(resp.Body).Decode(&out); err != nil {
689			return "", fmt.Errorf("ticket: decode search response: %w", err)
690		}
691		// Match on the field as well, in case the filter is not applied server side.
692		for _, t := range out {
693			if t.ExternalRef == ref {
694				return t.ID, nil
695			}
696		}
697		return "", nil
698	}
699	
700	// Create posts a ticket and returns its id.
701	func (c *Client) Create(ctx context.Context, t Ticket) (string, error) {
702		payload, err := json.Marshal(t)
703		if err != nil {
704			return "", err
705		}
706		req, err := http.NewRequestWithContext(ctx, http.MethodPost, c.url+"/tickets", bytes.NewReader(payload))
707		if err != nil {
708			return "", err
709		}
710		req.Header.Set("Content-Type", "application/json")
711		resp, err := c.do(ctx, req)
712		if err != nil {
713			return "", err
714		}
715		defer resp.Body.Close()
716		if err := checkStatus(resp, "create"); err != nil {
717			return "", err
718		}
719		var out struct {
720			ID string `json:"id"`
721		}
722		if err := json.NewDecoder(resp.Body).Decode(&out); err != nil {
723			return "", fmt.Errorf("ticket: decode response: %w", err)
724		}
725		return out.ID, nil
726	}
727	
728	func (c *Client) do(ctx context.Context, req *http.Request) (*http.Response, error) {
729		if err := c.limiter.wait(ctx); err != nil {
730			return nil, err
731		}
732		req.Header.Set("Authorization", "Bearer "+c.token)
733		return c.http.Do(req)
734	}
735	
736	func checkStatus(resp *http.Response, op string) error {
737		if resp.StatusCode == http.StatusTooManyRequests {
738			return ErrRateLimited
739		}
740		if resp.StatusCode < 200 || resp.StatusCode > 299 {
741			return fmt.Errorf("ticket: %s failed: status %d", op, resp.StatusCode)
742		}
743		return nil
744	}
