877	// Package relay turns scanner findings into tickets and chat notifications.
878	package relay
879	
880	import (
881		"context"
882		"errors"
883		"log/slog"
884		"sync"
885		"time"
886	
887		"northwick.example/finding-relay/internal/chat"
888		"northwick.example/finding-relay/internal/finding"
889		"northwick.example/finding-relay/internal/ticket"
890	)
891	
892	const (
893		retryDelay     = 10 * time.Second
894		rateLimitDelay = 5 * time.Second
895	)
896	
897	// Msg is the subset of a JetStream message the handler needs.
898	type Msg interface {
899		Data() []byte
900		Subject() string
901		Ack() error
902		Nak() error
903		NakWithDelay(delay time.Duration) error
904		Term() error
905	}
906	
907	// Handler processes one message at a time.
908	//
909	// The ticket platform is the source of truth for "already ticketed": before
910	// creating a ticket the handler looks one up by external_ref (the
911	// fingerprint). The in-memory maps only save API calls and remember a chat
912	// post that still has to go out.
913	type Handler struct {
914		log        *slog.Logger
915		tickets    *ticket.Client
916		chat       *chat.Client
917		suppressed map[string]bool
918	
919		mu      sync.Mutex
920		done    map[string]string // fingerprint -> ticket id, ticket and chat both sent
921		pending map[string]string // fingerprint -> ticket id ("" if the create outcome is unknown), chat post still owed
922	}
923	
924	// NewHandler wires a Handler.
925	func NewHandler(log *slog.Logger, tickets *ticket.Client, chat *chat.Client, suppressed map[string]bool) *Handler {
926		return &Handler{
927			log: log, tickets: tickets, chat: chat, suppressed: suppressed,
928			done: map[string]string{}, pending: map[string]string{},
929		}
930	}
931	
932	// Handle processes a single finding message.
933	func (h *Handler) Handle(ctx context.Context, m Msg) {
934		f, err := finding.Parse(m.Data())
935		if errors.Is(err, finding.ErrBadLine) {
936			h.log.Warn("finding breaks the contract, line ignored", "subject", m.Subject(), "fingerprint", f.Fingerprint)
937			err = nil
938		}
939		if err != nil {
940			// Redelivering a payload that does not parse will never succeed.
941			h.log.Error("bad finding, dropping", "subject", m.Subject(), "err", err)
