967			case id != "" && !owed:
968				log.Info("ticket already exists", "ticket", id)
969				h.markDone(f.Fingerprint, id)
970				_ = m.Ack()
971				return
972			case id == "":
973				// Remember the attempt: a create that times out or errors may
974				// still have opened the ticket, and then we owe the chat post.
975				h.setPending(f.Fingerprint, "")
976				id, err = h.tickets.Create(ctx, ticket.FromFinding(f))
