## Step 7. Wait out slow creates

**Why (from the incident):** on 15 Oct creates took up to 14 s. The relay gave up at 5 s and retried, so the ticket got created twice. Creates now get 15 s, and a retry waits 30 s.

**`internal/ticket/client.go`**: Replace the whole file with:

```go
// Package ticket talks to the ticketing platform.
package ticket

import (
	"bytes"
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"net/http"
	"net/url"
	"strings"
	"time"

	"northwick.example/finding-relay/internal/finding"
)

// Creates have been seen to take 14s on the platform side while it stays
// healthy (2026-10-15). Giving up earlier than that just opens a second
// ticket on retry. Search, create and the chat post together stay inside the
// consumer's 30s AckWait.
const (
	searchTimeout = 5 * time.Second
	createTimeout = 15 * time.Second
)

// ErrRateLimited is returned when the platform answers 429.
var ErrRateLimited = errors.New("ticket: rate limited")

// Ticket is the create request body.
type Ticket struct {
	Title       string   `json:"title"`
	Body        string   `json:"body"`
	Severity    string   `json:"severity"`
	ExternalRef string   `json:"external_ref"`
	Labels      []string `json:"labels"`
}

// FromFinding maps a finding to a ticket.
func FromFinding(f finding.Finding) Ticket {
	var b strings.Builder
	fmt.Fprintf(&b, "%s:%d\n\n%s\n\nMatch:\n%s\n", f.Path, f.Line, f.Description, f.SafeMatch())
	return Ticket{
		Title:       f.Title,
		Body:        b.String(),
		Severity:    f.Severity,
		ExternalRef: f.Fingerprint,
		Labels:      []string{"scanner:" + f.Scanner, "repo:" + f.Repo},
	}
}

// Client creates tickets.
type Client struct {
	url     string
	token   string
	http    *http.Client
	limiter *limiter
}

// New returns a Client for the platform at baseURL. perSecond caps the
// request rate of this client; 0 disables the cap.
func New(baseURL, token string, perSecond float64) *Client {
	return &Client{
		url:     strings.TrimRight(baseURL, "/"),
		token:   token,
		http:    &http.Client{},
		limiter: newLimiter(perSecond),
	}
}

// FindByExternalRef returns the id of an existing ticket with the given
// external_ref, or "" if there is none.
func (c *Client) FindByExternalRef(ctx context.Context, ref string) (string, error) {
	ctx, cancel := context.WithTimeout(ctx, searchTimeout)
	defer cancel()
	req, err := http.NewRequestWithContext(ctx, http.MethodGet, c.url+"/tickets?external_ref="+url.QueryEscape(ref), nil)
	if err != nil {
		return "", err
	}
	resp, err := c.do(ctx, req)
	if err != nil {
		return "", err
	}
	defer resp.Body.Close()
	if err := checkStatus(resp, "search"); err != nil {
		return "", err
	}
	var out []struct {
		ID          string `json:"id"`
		ExternalRef string `json:"external_ref"`
	}
	if err := json.NewDecoder(resp.Body).Decode(&out); err != nil {
		return "", fmt.Errorf("ticket: decode search response: %w", err)
	}
	// Match on the field as well, in case the filter is not applied server side.
	for _, t := range out {
		if t.ExternalRef == ref {
			return t.ID, nil
		}
	}
	return "", nil
}

// Create posts a ticket and returns its id.
func (c *Client) Create(ctx context.Context, t Ticket) (string, error) {
	payload, err := json.Marshal(t)
	if err != nil {
		return "", err
	}
	ctx, cancel := context.WithTimeout(ctx, createTimeout)
	defer cancel()
	req, err := http.NewRequestWithContext(ctx, http.MethodPost, c.url+"/tickets", bytes.NewReader(payload))
	if err != nil {
		return "", err
	}
	req.Header.Set("Content-Type", "application/json")
	resp, err := c.do(ctx, req)
	if err != nil {
		return "", err
	}
	defer resp.Body.Close()
	if err := checkStatus(resp, "create"); err != nil {
		return "", err
	}
	var out struct {
		ID string `json:"id"`
	}
	if err := json.NewDecoder(resp.Body).Decode(&out); err != nil {
		return "", fmt.Errorf("ticket: decode response: %w", err)
	}
	return out.ID, nil
}

func (c *Client) do(ctx context.Context, req *http.Request) (*http.Response, error) {
	if err := c.limiter.wait(ctx); err != nil {
		return nil, err
	}
	req.Header.Set("Authorization", "Bearer "+c.token)
	return c.http.Do(req)
}

func checkStatus(resp *http.Response, op string) error {
	if resp.StatusCode == http.StatusTooManyRequests {
		return ErrRateLimited
	}
	if resp.StatusCode < 200 || resp.StatusCode > 299 {
		return fmt.Errorf("ticket: %s failed: status %d", op, resp.StatusCode)
	}
	return nil
}
```

**`internal/relay/handler.go`**: Replace the whole file with:

```go
// Package relay turns scanner findings into tickets and chat notifications.
package relay

import (
	"context"
	"errors"
	"log/slog"
	"sync"
	"time"

	"northwick.example/finding-relay/internal/chat"
	"northwick.example/finding-relay/internal/finding"
	"northwick.example/finding-relay/internal/ticket"
)

const (
	// retryDelay is longer than the ticket client's create timeout, so a
	// create that is still running on the platform has finished before the
	// retry looks the ticket up.
	retryDelay     = 30 * time.Second
	rateLimitDelay = 5 * time.Second
)

// Msg is the subset of a JetStream message the handler needs.
type Msg interface {
	Data() []byte
	Subject() string
	Ack() error
	Nak() error
	NakWithDelay(delay time.Duration) error
	Term() error
}

// Handler processes one message at a time.
//
// The ticket platform is the source of truth for "already ticketed": before
// creating a ticket the handler looks one up by external_ref (the
// fingerprint). The in-memory maps only save API calls and remember a chat
// post that still has to go out.
type Handler struct {
	log        *slog.Logger
	tickets    *ticket.Client
	chat       *chat.Client
	suppressed map[string]bool

	mu      sync.Mutex
	done    map[string]string // fingerprint -> ticket id, ticket and chat both sent
	pending map[string]string // fingerprint -> ticket id ("" if the create outcome is unknown), chat post still owed
}

// NewHandler wires a Handler.
func NewHandler(log *slog.Logger, tickets *ticket.Client, chat *chat.Client, suppressed map[string]bool) *Handler {
	return &Handler{
		log: log, tickets: tickets, chat: chat, suppressed: suppressed,
		done: map[string]string{}, pending: map[string]string{},
	}
}

// Handle processes a single finding message.
func (h *Handler) Handle(ctx context.Context, m Msg) {
	f, err := finding.Parse(m.Data())
	if errors.Is(err, finding.ErrBadLine) {
		h.log.Warn("finding breaks the contract, line ignored", "subject", m.Subject(), "fingerprint", f.Fingerprint)
		err = nil
	}
	if err != nil {
		// Redelivering a payload that does not parse will never succeed.
		h.log.Error("bad finding, dropping", "subject", m.Subject(), "err", err)
		_ = m.Term()
		return
	}
	log := h.log.With("fingerprint", f.Fingerprint, "id", f.ID, "scanner", f.Scanner,
		"severity", f.Severity, "repo", f.Repo)
	log.Info("finding received")

	if h.suppressed[f.Fingerprint] {
		log.Info("finding suppressed")
		_ = m.Ack()
		return
	}
	if h.isDone(f.Fingerprint) {
		_ = m.Ack()
		return
	}

	id, owed := h.pendingChat(f.Fingerprint)
	if id == "" {
		id, err = h.tickets.FindByExternalRef(ctx, f.Fingerprint)
		if err != nil {
			h.retry(log, m, "ticket lookup failed", err)
			return
		}
		switch {
		case id != "" && !owed:
			log.Info("ticket already exists", "ticket", id)
			h.markDone(f.Fingerprint, id)
			_ = m.Ack()
			return
		case id == "":
			// Remember the attempt: a create that times out or errors may
			// still have opened the ticket, and then we owe the chat post.
			h.setPending(f.Fingerprint, "")
			id, err = h.tickets.Create(ctx, ticket.FromFinding(f))
			if err != nil {
				h.retry(log, m, "ticket create failed", err)
				return
			}
			log.Info("ticket created", "ticket", id)
		}
		owed = true
		h.setPending(f.Fingerprint, id)
	}

	if owed {
		if err := h.chat.Post(ctx, chat.FromFinding(f, id)); err != nil {
			log.Error("chat webhook failed, will retry", "ticket", id, "err", err)
			_ = m.NakWithDelay(retryDelay)
			return
		}
	}
	h.markDone(f.Fingerprint, id)
	_ = m.Ack()
}

func (h *Handler) retry(log *slog.Logger, m Msg, msg string, err error) {
	if errors.Is(err, ticket.ErrRateLimited) {
		log.Warn("ticket API rate limited, will retry")
		_ = m.NakWithDelay(rateLimitDelay)
		return
	}
	log.Error(msg+", will retry", "err", err)
	_ = m.NakWithDelay(retryDelay)
}

func (h *Handler) isDone(fp string) bool {
	h.mu.Lock()
	defer h.mu.Unlock()
	_, ok := h.done[fp]
	return ok
}

func (h *Handler) pendingChat(fp string) (string, bool) {
	h.mu.Lock()
	defer h.mu.Unlock()
	id, ok := h.pending[fp]
	return id, ok
}

func (h *Handler) setPending(fp, id string) {
	h.mu.Lock()
	defer h.mu.Unlock()
	h.pending[fp] = id
}

func (h *Handler) markDone(fp, id string) {
	h.mu.Lock()
	defer h.mu.Unlock()
	delete(h.pending, fp)
	h.done[fp] = id
}
