3093	// Package relay turns scanner findings into tickets and chat notifications.
3094	package relay
3095	
3096	import (
3097		"context"
3098		"errors"
3099		"log/slog"
3100		"sync"
3101		"time"
3102	
3103		"northwick.example/finding-relay/internal/chat"
3104		"northwick.example/finding-relay/internal/finding"
3105		"northwick.example/finding-relay/internal/ticket"
3106	)
3107	
3108	const (
3109		// retryDelay is longer than the ticket client's create timeout, so a
3110		// create that is still running on the platform has finished before the
3111		// retry looks the ticket up.
3112		retryDelay     = 30 * time.Second
3113		rateLimitDelay = 5 * time.Second
3114	)
3115	
3116	// Msg is the subset of a JetStream message the handler needs.
3117	type Msg interface {
3118		Data() []byte
3119		Subject() string
3120		Ack() error
3121		Nak() error
3122		NakWithDelay(delay time.Duration) error
3123		Term() error
3124	}
3125	
3126	// Handler processes one message at a time.
3127	//
3128	// The ticket platform is the source of truth for "already ticketed": before
3129	// creating a ticket the handler looks one up by external_ref (the
3130	// fingerprint). The in-memory maps only save API calls and remember a chat
3131	// post that still has to go out.
3132	type Handler struct {
3133		log        *slog.Logger
3134		tickets    *ticket.Client
3135		chat       *chat.Client
3136		suppressed map[string]bool
3137	
3138		// Contract is the findings contract version this relay tickets (1 or 2).
3139		// Messages in the other version are acked without a ticket: while the
3140		// scanners dual-publish, every finding arrives in both.
3141		Contract int
3142	
3143		mu      sync.Mutex
3144		done    map[string]string // fingerprint -> ticket id, ticket and chat both sent
3145		pending map[string]string // fingerprint -> ticket id ("" if the create outcome is unknown), chat post still owed
3146	}
3147	
3148	// NewHandler wires a Handler.
3149	func NewHandler(log *slog.Logger, tickets *ticket.Client, chat *chat.Client, suppressed map[string]bool) *Handler {
3150		return &Handler{
3151			log: log, tickets: tickets, chat: chat, suppressed: suppressed, Contract: 1,
3152			done: map[string]string{}, pending: map[string]string{},
3153		}
3154	}
3155	
3156	// Handle processes a single finding message.
3157	func (h *Handler) Handle(ctx context.Context, m Msg) {
3158		f, err := finding.Parse(m.Data())
3159		if errors.Is(err, finding.ErrBadLine) {
3160			h.log.Warn("finding breaks the contract, line ignored", "subject", m.Subject(), "fingerprint", f.Fingerprint)
3161			err = nil
3162		}
3163		if err != nil {
3164			// Redelivering a payload that does not parse will never succeed.
3165			h.log.Error("bad finding, dropping", "subject", m.Subject(), "err", err)
3166			_ = m.Term()
3167			return
3168		}
3169		log := h.log.With("fingerprint", f.Fingerprint, "id", f.ID, "scanner", f.Scanner,
3170			"severity", f.Severity, "repo", f.Repo)
3171		if f.Version != h.Contract {
3172			log.Debug("finding in another contract version, skipped", "version", f.Version)
3173			_ = m.Ack()
3174			return
3175		}
3176		log.Info("finding received")
3177	
3178		if h.suppressed[f.Fingerprint] || (f.LegacyFingerprint != "" && h.suppressed[f.LegacyFingerprint]) {
3179			log.Info("finding suppressed")
3180			_ = m.Ack()
3181			return
3182		}
3183		if h.isDone(f.Fingerprint) {
3184			_ = m.Ack()
3185			return
3186		}
3187	
3188		id, owed := h.pendingChat(f.Fingerprint)
3189		if id == "" {
3190			id, err = h.findTicket(ctx, f)
3191			if err != nil {
3192				h.retry(log, m, "ticket lookup failed", err)
3193				return
3194			}
3195			switch {
3196			case id != "" && !owed:
3197				log.Info("ticket already exists", "ticket", id)
3198				h.markDone(f.Fingerprint, id)
3199				_ = m.Ack()
3200				return
3201			case id == "":
3202				// Remember the attempt: a create that times out or errors may
3203				// still have opened the ticket, and then we owe the chat post.
3204				h.setPending(f.Fingerprint, "")
3205				id, err = h.tickets.Create(ctx, ticket.FromFinding(f))
3206				if err != nil {
3207					h.retry(log, m, "ticket create failed", err)
3208					return
3209				}
3210				log.Info("ticket created", "ticket", id)
3211			}
3212			owed = true
3213			h.setPending(f.Fingerprint, id)
3214		}
3215	
3216		if owed {
3217			if err := h.chat.Post(ctx, chat.FromFinding(f, id)); err != nil {
3218				log.Error("chat webhook failed, will retry", "ticket", id, "err", err)
3219				_ = m.NakWithDelay(retryDelay)
3220				return
3221			}
3222		}
3223		h.markDone(f.Fingerprint, id)
3224		_ = m.Ack()
3225	}
3226	
3227	// findTicket looks the finding up by fingerprint and, for a v2 finding that
3228	// carries its v1 fingerprint, by that too: tickets opened before the contract
3229	// change have the v1 fingerprint as external_ref.
3230	func (h *Handler) findTicket(ctx context.Context, f finding.Finding) (string, error) {
3231		id, err := h.tickets.FindByExternalRef(ctx, f.Fingerprint)
3232		if err != nil || id != "" || f.LegacyFingerprint == "" {
3233			return id, err
3234		}
3235		return h.tickets.FindByExternalRef(ctx, f.LegacyFingerprint)
3236	}
3237	
3238	func (h *Handler) retry(log *slog.Logger, m Msg, msg string, err error) {
3239		if errors.Is(err, ticket.ErrRateLimited) {
3240			log.Warn("ticket API rate limited, will retry")
3241			_ = m.NakWithDelay(rateLimitDelay)
3242			return
3243		}
3244		log.Error(msg+", will retry", "err", err)
3245		_ = m.NakWithDelay(retryDelay)
3246	}
3247	
3248	func (h *Handler) isDone(fp string) bool {
3249		h.mu.Lock()
3250		defer h.mu.Unlock()
3251		_, ok := h.done[fp]
3252		return ok
3253	}
3254	
3255	func (h *Handler) pendingChat(fp string) (string, bool) {
3256		h.mu.Lock()
3257		defer h.mu.Unlock()
3258		id, ok := h.pending[fp]
3259		return id, ok
3260	}
3261	
3262	func (h *Handler) setPending(fp, id string) {
3263		h.mu.Lock()
3264		defer h.mu.Unlock()
3265		h.pending[fp] = id
3266	}
3267	
3268	func (h *Handler) markDone(fp, id string) {
3269		h.mu.Lock()
3270		defer h.mu.Unlock()
3271		delete(h.pending, fp)
3272		h.done[fp] = id
3273	}
