	}
	if want := "high Issue in northwick/ledger (T-1)"; s.messages[0].Text != want || s.messages[0].Match != "secret-ish" {
		t.Fatalf("message = %+v", s.messages[0])
	}
}

func TestDuplicateFingerprint(t *testing.T) {
	h, s := newHandler(t, "")
